import { useEffect, useState } from 'react'
import Cards from '../../components/Cards/Cards'
import ProdCategory from '../../components/ProdCategory/ProdCategory'

import './Products.css'

 export const Products =()=> {
    const [data, setData] = useState([])
    useEffect(()=>{
        fetch('https://fakestoreapi.com/products').then((res)=>res.json()).then((res)=>setData(res) )
    })

    return(
        <div className='mainProducts'>

           <div className='class'>
           {data.map((elm)=> {
                return(
                    <div>
                        <Cards id={elm.id} image={elm.image} title={elm.title} price={elm.price}/>
                    </div>
                )
            })}
           </div>
        </div>
    )
}
